        ("What does response.json() return?", ["The raw response body as str", "A Python object parsed from the JSON body", "The request URL", "A JSON-encoded str"], 1, "json() decodes the body using json.loads and returns a dict, list, or scalar value."),
        ("Which HTTP status code signals that a resource was created?", ["200", "201", "204", "301"], 1, "201 Created is the standard status returned after successfully creating a resource."),
        ("Which library supports both synchronous and asynchronous HTTP requests?", ["requests", "httpx", "urllib.parse", "json"], 1, "httpx offers a requests-like API plus AsyncClient, while the requests library is synchronous only."),
        ("What does response.raise_for_status() do?", ["Prints the status code", "Raises an HTTPError for 4xx and 5xx responses", "Retries the request automatically", "Returns a boolean"], 1, "It raises requests.exceptions.HTTPError for client and server errors and stays silent for 2xx and 3xx responses."),
        ("Which HTTP method is intended for partial updates in a REST API?", ["GET", "POST", "PATCH", "DELETE"], 2, "PATCH updates only the fields supplied, whereas PUT is intended to replace the entire resource."),
